typedef struct {
  int num[20001], order[20001], head, tail;
} Q;

typedef struct {
  Q cats;
  Q dogs;
  int order;
} AnimalShelf;

AnimalShelf *animalShelfCreate(void) {
  AnimalShelf *obj = (AnimalShelf *)malloc(sizeof(AnimalShelf));
  obj->cats.head = obj->cats.tail = 0;
  obj->dogs.head = obj->dogs.tail = 0;
  obj->order = 0;
  return obj;
}

void animalShelfEnqueue(AnimalShelf *obj, int *animal, int animalSize) {
  (void)animalSize;
  if (animal[1] == 0) {
    obj->cats.num[obj->cats.tail] = animal[0];
    obj->cats.order[obj->cats.tail] = obj->order++;
    obj->cats.tail++;
  } else {
    obj->dogs.num[obj->dogs.tail] = animal[0];
    obj->dogs.order[obj->dogs.tail] = obj->order++;
    obj->dogs.tail++;
  }
}

void animalShelfDequeueAny(AnimalShelf *obj, int *res) {
  int hasCat = obj->cats.head < obj->cats.tail;
  int hasDog = obj->dogs.head < obj->dogs.tail;
  if (!hasCat && !hasDog) {
    res[0] = res[1] = -1;
    return;
  }
  if (hasCat && (!hasDog || obj->cats.order[obj->cats.head] < obj->dogs.order[obj->dogs.head])) {
    res[0] = obj->cats.num[obj->cats.head++];
    res[1] = 0;
  } else {
    res[0] = obj->dogs.num[obj->dogs.head++];
    res[1] = 1;
  }
}

void animalShelfDequeueDog(AnimalShelf *obj, int *res) {
  if (obj->dogs.head < obj->dogs.tail) {
    res[0] = obj->dogs.num[obj->dogs.head++];
    res[1] = 1;
  } else {
    res[0] = res[1] = -1;
  }
}

void animalShelfDequeueCat(AnimalShelf *obj, int *res) {
  if (obj->cats.head < obj->cats.tail) {
    res[0] = obj->cats.num[obj->cats.head++];
    res[1] = 0;
  } else {
    res[0] = res[1] = -1;
  }
}

class AnimalShelf {
  queue<pair<int, int>> cats;
  queue<pair<int, int>> dogs;
  int order = 0;

public:
  AnimalShelf() {}
  void enqueue(vector<int> animal) {
    if (animal[1] == 0) {
      cats.push({animal[0], order++});
    } else {
      dogs.push({animal[0], order++});
    }
  }
  vector<int> dequeueAny() {
    if (cats.empty() && dogs.empty()) return {-1, -1};
    if (dogs.empty() || (!cats.empty() && cats.front().second < dogs.front().second)) {
      vector<int> res = {cats.front().first, 0};
      cats.pop();
      return res;
    }
    vector<int> res = {dogs.front().first, 1};
    dogs.pop();
    return res;
  }
  vector<int> dequeueDog() {
    if (dogs.empty()) return {-1, -1};
    vector<int> res = {dogs.front().first, 1};
    dogs.pop();
    return res;
  }
  vector<int> dequeueCat() {
    if (cats.empty()) return {-1, -1};
    vector<int> res = {cats.front().first, 0};
    cats.pop();
    return res;
  }
};

type entry struct {
	num   int
	order int
}

type AnimalShelf struct {
	cats  []entry
	dogs  []entry
	order int
}

func Constructor() AnimalShelf {
	return AnimalShelf{}
}

func (a *AnimalShelf) Enqueue(animal []int) {
	if animal[1] == 0 {
		a.cats = append(a.cats, entry{animal[0], a.order})
	} else {
		a.dogs = append(a.dogs, entry{animal[0], a.order})
	}
	a.order++
}

func (a *AnimalShelf) DequeueAny() []int {
	if len(a.cats) == 0 && len(a.dogs) == 0 {
		return []int{-1, -1}
	}
	if len(a.dogs) == 0 || (len(a.cats) > 0 && a.cats[0].order < a.dogs[0].order) {
		res := []int{a.cats[0].num, 0}
		a.cats = a.cats[1:]
		return res
	}
	res := []int{a.dogs[0].num, 1}
	a.dogs = a.dogs[1:]
	return res
}

func (a *AnimalShelf) DequeueDog() []int {
	if len(a.dogs) == 0 {
		return []int{-1, -1}
	}
	res := []int{a.dogs[0].num, 1}
	a.dogs = a.dogs[1:]
	return res
}

func (a *AnimalShelf) DequeueCat() []int {
	if len(a.cats) == 0 {
		return []int{-1, -1}
	}
	res := []int{a.cats[0].num, 0}
	a.cats = a.cats[1:]
	return res
}

class AnimalShelf {
  private static class Entry {
    int num, order;
    Entry(int num, int order) {
      this.num = num;
      this.order = order;
    }
  }

  private Deque<Entry> cats = new ArrayDeque<>();
  private Deque<Entry> dogs = new ArrayDeque<>();
  private int order = 0;

  public AnimalShelf() {}

  public void enqueue(int[] animal) {
    if (animal[1] == 0) cats.addLast(new Entry(animal[0], order++));
    else dogs.addLast(new Entry(animal[0], order++));
  }

  public int[] dequeueAny() {
    if (cats.isEmpty() && dogs.isEmpty()) return new int[] { -1, -1 };
    if (dogs.isEmpty() || (!cats.isEmpty() && cats.peekFirst().order < dogs.peekFirst().order)) {
      return new int[] { cats.pollFirst().num, 0 };
    }
    return new int[] { dogs.pollFirst().num, 1 };
  }

  public int[] dequeueDog() {
    if (dogs.isEmpty()) return new int[] { -1, -1 };
    return new int[] { dogs.pollFirst().num, 1 };
  }

  public int[] dequeueCat() {
    if (cats.isEmpty()) return new int[] { -1, -1 };
    return new int[] { cats.pollFirst().num, 0 };
  }
}

